#!/bin/bash
#SBATCH --job-name=FullTM_amset
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=2
#SBATCH --mem=32G
#SBATCH --partition=v100m3
#SBATCH --output=amset-%j.out
#SBATCH --error=amset-%j.err
set -eo pipefail
source /data/app/anaconda3/2024.10-1/bin/activate
conda activate python
set -u
command -v amset >/dev/null
export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1
# Set an available CPU partition above if v100m3 requires GPUs.
python - <<'AMSET_PYTHON'
import os,sys,json
from pathlib import Path
# Units: doping cm^-3 (negative electrons); temperatures K; tau seconds.
# Outputs: transport mass in m_e; CONSTANT-tau mobility in cm^2/(V s).
root=Path('/data/home/lichaoyue/26-10-LHL_cal/Dos/Full_TM')
source=root/'runs/dos/attempt_002'
if not any((source/n).is_file() for n in ('vasprun.xml','vasprun.xml.gz')):
    raise FileNotFoundError(f'Missing vasprun.xml[.gz]: {source}')
task=root/'amset_single_script'
task.mkdir(parents=True,exist_ok=True)
files={'checkpoint_utils.py': "import os\nimport json\nfrom contextlib import contextmanager\n\ndef _save(path, value):\n    temporary = path.with_suffix(path.suffix + '.tmp')\n    with temporary.open('w', encoding='utf-8') as handle:\n        json.dump(value, handle, indent=2)\n        handle.flush()\n        os.fsync(handle.fileno())\n    temporary.replace(path)\n\n@contextmanager\ndef _lock(root):\n    with (root / '.workflow.lock').open('a+b') as handle:\n        handle.seek(0)\n        if os.name == 'nt':\n            import msvcrt\n            if handle.read(1) == b'':\n                handle.write(b'0')\n                handle.flush()\n            handle.seek(0)\n            try:\n                msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)\n            except OSError as error:\n                raise RuntimeError('Another workflow is using this task directory') from error\n        else:\n            import fcntl\n            try:\n                fcntl.flock(handle, fcntl.LOCK_EX | fcntl.LOCK_NB)\n            except OSError as error:\n                raise RuntimeError('Another workflow is using this task directory') from error\n        try:\n            yield\n        finally:\n            if os.name == 'nt':\n                handle.seek(0)\n                msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)\n            else:\n                fcntl.flock(handle, fcntl.LOCK_UN)\n\n", 'completed_local.py': '"""Resolve completed VASP stages for readers and follow-up workflows."""\n\nimport json\nfrom pathlib import Path\n\n\ndef get_completed_result(task_dir, stage, *, source_dir=None, validate=True, require_uniform=False):\n    """Return a completed relax/static/dos/band directory without modifying it.\n\n    Prefer the named completed checkpoint; relative directories use task_dir.\n    A raw VASP directory can be passed as task_dir or explicitly source_dir.\n    validate checks electronic convergence, ionic convergence for relax, NSW\n    semantics and rejects line-mode k points for DOS or require_uniform=True.\n    This excludes explicit path mode, not a full grid completeness proof. No wavefunction/charge\n    files required for read-only reuse; downstream calculations check theirs.\n    Requires pymatgen only when validate=True. No random seed or file writes.\n    """\n    if stage not in {"relax", "static", "dos", "band"}:\n        raise ValueError("stage must be relax, static, dos or band")\n    root = Path(task_dir).resolve()\n    if source_dir is not None:\n        directory = Path(source_dir)\n        directory = directory if directory.is_absolute() else root / directory\n    elif (root / "workflow_state.json").is_file():\n        state = json.loads((root / "workflow_state.json").read_text(encoding="utf-8"))\n        entry = state.get("stages", {}).get(stage, {})\n        if entry.get("status") != "completed" or not entry.get("directory"):\n            raise ValueError(f"No completed {stage} checkpoint in {root}; specify a verified source_dir")\n        directory = Path(entry["directory"])\n        directory = directory if directory.is_absolute() else root / directory\n    else:\n        directory = root\n    directory = directory.resolve()\n    xml = next((directory / name for name in ("vasprun.xml", "vasprun.xml.gz")\n                if (directory / name).is_file()), None)\n    if xml is None:\n        raise FileNotFoundError(f"No vasprun.xml[.gz] for {stage}: {directory}")\n    if validate:\n        from pymatgen.io.vasp.outputs import Vasprun\n        run = Vasprun(xml, parse_dos=False, parse_eigen=False,\n                      parse_projected_eigen=False, parse_potcar_file=False,\n                      exception_on_bad_xml=True)\n        if not run.converged_electronic:\n            raise ValueError(f"Electronic calculation is not converged: {directory}")\n        nsw = int(run.parameters.get("NSW", 0))\n        if stage == "relax" and (nsw <= 0 or not run.converged_ionic):\n            raise ValueError(f"Not a completed ionic relaxation: {directory}")\n        if stage != "relax" and nsw != 0:\n            raise ValueError(f"{stage} requires NSW=0: {directory}")\n        if (stage == "dos" or require_uniform) and "line" in str(run.kpoints.style).lower():\n            raise ValueError("DOS/transport requires a uniform grid, not line-mode k points")\n    return directory\n', 'amset_crt_local.py': '"""Restartable AMSET CRT postprocessing; no VASP or scattering jobs submitted."""\n\nimport argparse\nimport gzip\nimport hashlib\nimport json\nimport math\nimport shutil\nimport subprocess\nfrom pathlib import Path\n\nfrom checkpoint_utils import _lock, _save\n\n\ndef _transport(directory, tau):\n    files = sorted(directory.glob("transport_*.json*"))\n    if len(files) != 1:\n        raise ValueError(f"Expected one AMSET transport JSON in {directory}, found {len(files)}")\n    opener = gzip.open if files[0].suffix == ".gz" else open\n    with opener(files[0], "rt", encoding="utf-8") as handle:\n        data = json.load(handle)\n    doping, temperatures = data["doping"], data["temperatures"]\n    sigma = data["conductivity"]\n    if len(sigma) != len(doping) or any(len(row) != len(temperatures) for row in sigma):\n        raise ValueError("Invalid AMSET conductivity dimensions")\n    ratio = []\n    for row in sigma:\n        tensors = []\n        for tensor in row:\n            if len(tensor) != 3 or any(len(axis) != 3 for axis in tensor):\n                raise ValueError("Expected 3x3 conductivity tensors")\n            if any(not math.isfinite(float(v)) for axis in tensor for v in axis):\n                raise ValueError("Nonfinite AMSET conductivity")\n            tensors.append([[float(v) / tau for v in axis] for axis in tensor])\n        ratio.append(tensors)\n    return {\n        "doping_cm3": doping, "temperatures_K": temperatures,\n        "carrier_type": ["electron" if d < 0 else "hole" for d in doping],\n        "relaxation_time_s": tau, "conductivity_S_m": sigma,\n        "sigma_over_tau_S_m_s": ratio,\n        "tensor_axes": ["doping", "temperature", "cartesian_i", "cartesian_j"],\n        "transport_file": str(files[0]),\n    }\n\n\ndef run_amset_crt(source_dir, output_dir, *, doping=(-1e18, 1e18),\n                  temperatures=(300,), relaxation_time=1e-14,\n                  interpolation_factor=10, nworkers=1, resume=True):\n    """Calculate sigma/tau from an existing uniform-grid vasprun.xml[.gz].\n\n    Doping is cm^-3 (negative electrons, positive holes), temperatures K,\n    relaxation_time seconds. Returned tensors have shape (ndoping, nT, 3, 3)\n    and sigma/tau units S m^-1 s^-1. Requires an environment with AMSET CLI.\n    Writes isolated attempt directories, logs, settings and a JSON checkpoint;\n    copies the source XML, never runs VASP. Identical successful requests are\n    reused; failures/changed requests create another attempt. No random seed.\n    Resume is at completed-calculation level, not inside AMSET interpolation.\n    """\n    source, root = Path(source_dir).resolve(), Path(output_dir).resolve()\n    xml = next((source / name for name in ("vasprun.xml", "vasprun.xml.gz")\n                if (source / name).is_file()), None)\n    if xml is None:\n        raise FileNotFoundError(f"No vasprun.xml[.gz] in {source}; supply the actual DOS output directory")\n    if source == root or source in root.parents or root in source.parents:\n        raise ValueError("Use separate source and output directories, neither nested in the other")\n    doping = [float(x) for x in doping]\n    temperatures = [float(x) for x in temperatures]\n    if not doping or any(not math.isfinite(x) or x == 0 for x in doping):\n        raise ValueError("doping must contain finite nonzero concentrations")\n    if not temperatures or any(not math.isfinite(x) or x <= 0 for x in temperatures):\n        raise ValueError("temperatures must be positive and finite")\n    tau = float(relaxation_time)\n    if not math.isfinite(tau) or tau <= 0:\n        raise ValueError("relaxation_time must be positive seconds")\n    if any(isinstance(x, bool) or not isinstance(x, int) or x < 1\n           for x in (interpolation_factor, nworkers)):\n        raise ValueError("interpolation_factor and nworkers must be positive integers")\n    settings = dict(scattering_type=["CRT"], constant_relaxation_time=tau,\n                    doping=doping, temperatures=temperatures,\n                    interpolation_factor=interpolation_factor, nworkers=nworkers,\n                    file_format="json", write_mesh=False, unity_overlap=True)\n    digest = hashlib.sha256()\n    with xml.open("rb") as handle:\n        for chunk in iter(lambda: handle.read(1024 * 1024), b""):\n            digest.update(chunk)\n    fingerprint = hashlib.sha256((digest.hexdigest() + json.dumps(settings, sort_keys=True)).encode()).hexdigest()\n    root.mkdir(parents=True, exist_ok=True)\n    with _lock(root):\n        checkpoint = root / "amset_crt_state.json"\n        state = json.loads(checkpoint.read_text(encoding="utf-8")) if checkpoint.exists() else {}\n        if resume and state.get("fingerprint") == fingerprint and state.get("status") == "completed":\n            result = _transport(root / state["attempt"], tau)\n            _save(root / "amset_crt_result.json", result)\n            return result\n        executable = shutil.which("amset")\n        if executable is None:\n            raise RuntimeError("AMSET CLI not found. Activate an environment containing amset before calling this function.")\n        index = 1\n        while (root / f"attempt_{index:03d}").exists():\n            index += 1\n        attempt = root / f"attempt_{index:03d}"\n        attempt.mkdir()\n        state = dict(status="running", fingerprint=fingerprint, attempt=attempt.name,\n                     source=str(xml), settings=settings)\n        _save(checkpoint, state)\n        try:\n            if xml.suffix == ".gz":\n                with gzip.open(xml, "rb") as src, (attempt / "vasprun.xml").open("wb") as dst:\n                    shutil.copyfileobj(src, dst)\n            else:\n                shutil.copy2(xml, attempt / "vasprun.xml")\n            # JSON is valid YAML; avoid an extra dependency just for settings.\n            _save(attempt / "settings.yaml", settings)\n            with (attempt / "amset.log").open("w", encoding="utf-8") as log:\n                subprocess.run([executable, "run"], cwd=attempt, stdout=log,\n                               stderr=subprocess.STDOUT, check=True)\n            result = _transport(attempt, tau)\n            _save(root / "amset_crt_result.json", result)\n            state["status"] = "completed"\n            _save(checkpoint, state)\n            return result\n        except Exception as error:\n            state.update(status="failed", error=f"{type(error).__name__}: {error}")\n            _save(checkpoint, state)\n            raise\n\n\ndef main():\n    """CLI with the same default electron/hole CRT settings as the Python API."""\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("source_dir")\n    parser.add_argument("output_dir")\n    parser.add_argument("--doping", nargs="+", type=float, default=[-1e18, 1e18])\n    parser.add_argument("--temperatures", nargs="+", type=float, default=[300])\n    parser.add_argument("--nworkers", type=int, default=1)\n    args = parser.parse_args()\n    run_amset_crt(**vars(args))\n\n\nif __name__ == "__main__":\n    main()\n', 'amset_postprocess_local.py': '"""Postprocess an existing DOS checkpoint using a single AMSET CRT calculation."""\n\nfrom pathlib import Path\n\nfrom amset_crt_local import run_amset_crt\nfrom checkpoint_utils import _save\nfrom completed_local import get_completed_result\n\n\ndef _dos_directory(workflow_root, source_dir=None, source_stage="dos"):\n    return get_completed_result(workflow_root, source_stage, source_dir=source_dir, require_uniform=True)\n\n\ndef _derived_properties(result):\n    # Same definition as AMSET tools/effmass.py: m*/m_e = n e² (sigma/tau)^-1 / m_e.\n    # n is the absolute net doping, not a separately computed band population.\n    import numpy as np\n\n    elementary_charge = 1.602176634e-19  # C, exact\n    electron_mass = 9.1093837139e-31  # kg, CODATA 2022\n    mass, average, mobility, normalized_mobility, notes = [], [], [], [], []\n    for index, doping in enumerate(result["doping_cm3"]):\n        number_density = abs(doping) * 1e6  # cm^-3 -> m^-3\n        mass_row, average_row, mobility_row, normalized_row, note_row = [], [], [], [], []\n        for tensor in result["sigma_over_tau_S_m_s"][index]:\n            conductivity_ratio = np.asarray(tensor, dtype=float)\n            mu_ratio = conductivity_ratio / (number_density * elementary_charge) * 1e4\n            normalized_row.append(mu_ratio.tolist())  # cm² V^-1 s^-2\n            mobility_row.append((mu_ratio * result["relaxation_time_s"]).tolist())\n            try:\n                symmetric = (conductivity_ratio + conductivity_ratio.T) / 2\n                if np.any(np.linalg.eigvalsh(symmetric) <= 0):\n                    raise ValueError("Conductivity tensor is not positive definite")\n                tensor_mass = np.linalg.inv(conductivity_ratio) * number_density * elementary_charge**2 / electron_mass\n                if not np.isfinite(tensor_mass).all():\n                    raise ValueError("Effective mass is nonfinite")\n                mass_row.append(tensor_mass.tolist())\n                average_row.append(float(3 / np.trace(np.linalg.inv(tensor_mass))))\n                note_row.append("ok")\n            except (ValueError, np.linalg.LinAlgError) as error:\n                mass_row.append(None)\n                average_row.append(None)\n                note_row.append(str(error))\n        mass.append(mass_row)\n        average.append(average_row)\n        mobility.append(mobility_row)\n        normalized_mobility.append(normalized_row)\n        notes.append(note_row)\n    result.update(\n        conductivity_effective_mass_m0=mass,\n        conductivity_effective_mass_harmonic_mean_m0=average,\n        effective_mass_status=notes,\n        mobility_crt_cm2_V_s=mobility,\n        mobility_over_tau_cm2_V_s2=normalized_mobility,\n        effective_mass_definition="AMSET eff-mass: abs(net doping) * e^2 * inverse(sigma/tau) / m_e",\n        mobility_definition="sigma / (abs(net doping) * e); constant user-supplied tau, not ab initio scattering mobility",\n    )\n    return result\n\n\ndef run_amset_postprocess(workflow_root, output_dir=None, *, source_dir=None,\n                          source_stage="dos",\n                          doping=(-1e18, 1e18), temperatures=(300,),\n                          relaxation_time=1e-14, interpolation_factor=10,\n                          nworkers=1, resume=True):\n    """Read a completed DOS task and export transport masses and CRT mobility.\n\n    workflow_root contains workflow_state.json; source_stage selects dos/static.\n    source_dir optionally overrides\n    the DOS path (relative to workflow_root). Default output is root/amset_results.\n    Units: doping cm^-3 (electrons negative), temperature K, tau s; mass in m_e,\n    mobility cm²/(V s), sigma/tau S/(m s). Tensor axes match run_amset_crt.\n    Requires AMSET and numpy; no random seed. Copies XML and writes only to the\n    independent output subtree; no VASP runs/submission or source modification.\n    Reuses completed CRT calculations by content/parameter fingerprint; derived\n    properties can be regenerated without recomputing AMSET. Invalid mass tensors\n    are null with a diagnostic; CRT success does not imply numerical convergence.\n    """\n    root = Path(workflow_root).resolve()\n    if source_stage not in {"dos", "static"}:\n        raise ValueError("AMSET requires a completed uniform DOS or static calculation")\n    source = _dos_directory(root, source_dir, source_stage)\n    target = Path(output_dir).resolve() if output_dir is not None else root / "amset_results"\n    result = run_amset_crt(source, target / "crt", doping=doping,\n                           temperatures=temperatures, relaxation_time=relaxation_time,\n                           interpolation_factor=interpolation_factor,\n                           nworkers=nworkers, resume=resume)\n    result = _derived_properties(result)\n    result["source_dir"] = str(source)\n    _save(target / "transport_properties.json", result)\n    # Flat table for quick plotting; retain the complete tensors in JSON.\n    import csv\n    with (target / "transport_summary.csv").open("w", newline="", encoding="utf-8") as handle:\n        writer = csv.writer(handle)\n        writer.writerow(["carrier", "doping_cm-3", "temperature_K", "mass_harmonic_m0",\n                         "mass_xx_m0", "mass_yy_m0", "mass_zz_m0",\n                         "sigma_over_tau_xx_S_m_s", "sigma_over_tau_yy_S_m_s", "sigma_over_tau_zz_S_m_s",\n                         "mobility_crt_xx_cm2_V_s", "mobility_crt_yy_cm2_V_s", "mobility_crt_zz_cm2_V_s"])\n        for n, concentration in enumerate(result["doping_cm3"]):\n            for t, temperature in enumerate(result["temperatures_K"]):\n                mass_tensor = result["conductivity_effective_mass_m0"][n][t]\n                writer.writerow([result["carrier_type"][n], concentration, temperature,\n                                 result["conductivity_effective_mass_harmonic_mean_m0"][n][t],\n                                 *([mass_tensor[i][i] for i in range(3)] if mass_tensor else [None]*3),\n                                 *[result["sigma_over_tau_S_m_s"][n][t][i][i] for i in range(3)],\n                                 *[result["mobility_crt_cm2_V_s"][n][t][i][i] for i in range(3)]])\n    return result\n'}
for name,content in files.items():
    (task/name).write_text(content,encoding='utf-8')
sys.path.insert(0,str(task))
from amset_postprocess_local import run_amset_postprocess
config=dict(source_dir='runs/dos/attempt_002',source_stage='dos',doping=[-1e18,1e18],
            temperatures=[300],relaxation_time=1e-14,interpolation_factor=10,
            nworkers=int(os.environ.get('SLURM_CPUS_PER_TASK','2')))
(task/'postprocess.json').write_text(json.dumps(config,indent=2),encoding='utf-8')
run_amset_postprocess(root,task/'results',**config)
print('Results:',task/'results/transport_summary.csv')
AMSET_PYTHON
